-- Drug knowledge data enrichment script
-- Generated from exported drug, drug_label and dosing_guideline tables.
-- This script only fills currently empty fields and keeps existing non-empty values.
-- It does not invent DrugBank/PubChem/KEGG identifiers.
USE biomed;

START TRANSACTION;

-- Optional backups. Run once before applying updates.
CREATE TABLE IF NOT EXISTS drug_backup_before_knowledge_update AS SELECT * FROM drug;
CREATE TABLE IF NOT EXISTS drug_label_backup_before_knowledge_update AS SELECT * FROM drug_label;
CREATE TABLE IF NOT EXISTS dosing_guideline_backup_before_knowledge_update AS SELECT * FROM dosing_guideline;

-- 1. Fill empty drug-level knowledge fields.
UPDATE drug
SET
    description = CASE WHEN description IS NULL OR TRIM(description) = '' THEN 'aripiprazole is a drug entry in the pharmacogenomic knowledge base. The record supports drug information browsing, label review, and gene-drug matching interpretation within the precision medicine system.' ELSE description END,
    biomarker_associated = CASE WHEN biomarker_associated IS NULL THEN 1 ELSE biomarker_associated END,
    pharmgkb_id = CASE WHEN pharmgkb_id IS NULL OR TRIM(pharmgkb_id) = '' THEN 'PA10026' ELSE pharmgkb_id END
WHERE id = 'PA10026';
