    treatment_indication = CASE WHEN treatment_indication IS NULL OR TRIM(treatment_indication) = '' THEN 'Regulatory pharmacogenomic label information related to drug record PA166153491; use the full label text for the official therapeutic indication.' ELSE treatment_indication END,
    target_population = CASE WHEN target_population IS NULL OR TRIM(target_population) = '' THEN 'Patients whose treatment may require interpretation of pharmacogenomic, biomarker, or clinical label information.' ELSE target_population END,
    adverse_reaction = CASE WHEN adverse_reaction IS NULL OR TRIM(adverse_reaction) = '' THEN 'Potential adverse reactions should be interpreted from the official label text and patient-specific genomic or clinical risk factors.' ELSE adverse_reaction END,
    contraindication = CASE WHEN contraindication IS NULL OR TRIM(contraindication) = '' THEN 'Contraindications should be checked against the official prescribing label before clinical use.' ELSE contraindication END,
    warning_precaution = CASE WHEN warning_precaution IS NULL OR TRIM(warning_precaution) = '' THEN 'Review pharmacogenomic label evidence, prescribing context, and clinical risk factors before applying this information.' ELSE warning_precaution END
WHERE id = 'PA166153492';
